(function () {
  'use strict';
  // Balance transfer optimizer: split up to four card balances across one or two promo cards.
  //   Transfers: every way of assigning each card to "stays", promo card 1 or promo card 2 is
  //     tried (3^4 = 81 at most). Within a promo card, assigned cards are filled highest APR
  //     first; each transfer t plus its fee t x fee% must fit in the remaining limit, so
  //     t = min(balance, room / (1 + fee%)), rounded down to the cent. The fee is added to the
  //     promo balance; anything that does not fit stays on the original card.
  //   Monthly plan with one fixed budget: each open card is charged interest = balance x APR / 12
  //     (rounded to the cent; a promo card uses its intro APR for the intro months, then the
  //     later APR) and paid its minimum = max($25, interest + 1% of the balance), capped at what
  //     it owes. Two ways to use the rest are tried for every assignment:
  //       "highest rate first": everything left goes to the card with the highest current APR;
  //       "clear promos first": each promo card still in its intro period is first topped up to
  //         the level payment that clears it by the end of the intro period, then highest rate.
  //   A plan whose minimums ever exceed the budget is skipped. The cheapest plan (interest +
  //   fees; ties -> sooner payoff) is shown and compared with no transfer (highest rate first).
  //   Payment to clear a promo card = level payment on (moved + fee) at the intro APR over the
  //   intro months, rounded up to the cent.
  // Verified (scratchpad b6credit/bt.test.js): $5,000 moved at 3% to a 0% / 15-month card ->
  //   fee $150, payment to clear $343.34 (5,150 / 15 rounded up); filling: $8,000 limit, 3% fee,
  //   cards $6,500 + $3,200 -> $3,200 (fee $96) then $4,566.99 (fee $137.01) fills $8,000;
  //   no-transfer plan for one card ($10,000 at 12%, $222.45 budget) -> 60 months, interest
  //   within $0.10 of the closed form; the chosen plan never costs more than the no-transfer
  //   plan, and equals a brute-force re-run in the test; total paid = balances + interest + fees.

  // ---- Calculation ----
  var MAX_MONTHS = 1200, MIN_FLOOR = 25, MIN_PCT = 0.01;
  function cents(x) { return Math.round(x * 100) / 100; }
  function levelPayment(amount, apr, months) {
    if (months <= 0) return amount;
    var i = apr / 12;
    return i === 0 ? amount / months : amount * i / (1 - Math.pow(1 + i, -months));
  }
  function aprAt(d, m) { return d.introMonths && m <= d.introMonths ? d.introApr : d.apr; }

  // cards: [{ balance, apr }]; offers: [{ limit, fee, introApr, introMonths, apr }];
  // assign[i]: 0 = stays, k = promo card k.
  function buildDebts(cards, offers, assign) {
    var moves = cards.map(function () { return offers.map(function () { return 0; }); });
    var fees = offers.map(function () { return 0; }), moved = offers.map(function () { return 0; });
    offers.forEach(function (o, k) {
      var room = o.limit;
      var idx = cards.map(function (c, i) { return i; }).filter(function (i) { return assign[i] === k + 1; })
        .sort(function (a, b) { return (cards[b].apr - cards[a].apr) || (a - b); });
      idx.forEach(function (i) {
        var t = Math.min(cards[i].balance, Math.floor(room / (1 + o.fee) * 100 + 1e-6) / 100);
        if (t <= 0) return;
        var f = cents(t * o.fee);
        moves[i][k] = t; moved[k] += t; fees[k] += f; room -= t + f;
      });
    });
    var debts = [];
    cards.forEach(function (c, i) {
      var left = cents(c.balance - moves[i].reduce(function (s, v) { return s + v; }, 0));
      debts.push({ balance: left, apr: c.apr, introApr: 0, introMonths: 0, promo: -1, card: i });
    });
    offers.forEach(function (o, k) {
      debts.push({ balance: cents(moved[k] + fees[k]), apr: o.apr, introApr: o.introApr, introMonths: o.introMonths, promo: k, card: -1 });
    });
    return { debts: debts, moves: moves, fees: fees, moved: moved };
  }

  function simulate(debts, budget, rule) {
    var n = debts.length, bal = debts.map(function (d) { return d.balance; });
    var paidOff = debts.map(function (d) { return d.balance > 0.005 ? 0 : -1; });
    var interestTotal = 0, paidTotal = 0;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var i, open = 0, start = bal.slice(), pays = debts.map(function () { return 0; }), mins = 0;
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) continue;
        var interest = cents(bal[i] * aprAt(debts[i], m) / 12);
        bal[i] = cents(bal[i] + interest); interestTotal += interest;
        pays[i] = Math.min(bal[i], cents(Math.max(MIN_FLOOR, interest + MIN_PCT * start[i])));
        mins += pays[i];
      }
      if (mins > budget + 0.005) return { feasible: false };
      var avail = budget - mins;
      if (rule === 'promo') {
        for (i = 0; i < n && avail > 0.005; i++) {
          var d = debts[i];
          if (d.promo < 0 || bal[i] <= 0.005 || m > d.introMonths) continue;
          var target = Math.min(bal[i], Math.ceil(levelPayment(start[i], d.introApr, d.introMonths - m + 1) * 100 - 1e-6) / 100);
          var top = Math.min(avail, Math.max(0, target - pays[i]));
          pays[i] += top; avail -= top;
        }
      }
      var order = [];
      for (i = 0; i < n; i++) if (bal[i] - pays[i] > 0.005) order.push(i);
      order.sort(function (a, b) { return (aprAt(debts[b], m) - aprAt(debts[a], m)) || (bal[a] - bal[b]) || (a - b); });
      for (var k = 0; k < order.length && avail > 0.005; k++) {
        var j = order[k], more = Math.min(avail, bal[j] - pays[j]);
        pays[j] += more; avail -= more;
      }
      for (i = 0; i < n; i++) {
        if (bal[i] <= 0.005) continue;
        bal[i] = cents(bal[i] - pays[i]); paidTotal += pays[i];
        if (bal[i] <= 0.005) { bal[i] = 0; paidOff[i] = m; } else open++;
      }
      if (!open) return { feasible: true, done: true, months: m, interest: interestTotal, paid: paidTotal, paidOff: paidOff };
    }
    return { feasible: true, done: false, months: MAX_MONTHS, interest: interestTotal, paid: paidTotal, paidOff: paidOff };
  }

  function optimize(cards, offers, budget) {
    var none = cards.map(function () { return 0; });
    var base = simulate(buildDebts(cards, offers, none).debts, budget, 'rate');
    var best = null, total = Math.pow(offers.length + 1, cards.length);
    for (var code = 0; code < total; code++) {
      var assign = [], c = code;
      for (var i = 0; i < cards.length; i++) { assign.push(c % (offers.length + 1)); c = Math.floor(c / (offers.length + 1)); }
      var built = buildDebts(cards, offers, assign);
      var feeSum = built.fees.reduce(function (s, v) { return s + v; }, 0);
      ['rate', 'promo'].forEach(function (rule) {
        var sim = simulate(built.debts, budget, rule);
        if (!sim.feasible || !sim.done) return;
        var cost = sim.interest + feeSum;
        if (!best || cost < best.cost - 0.005 || (Math.abs(cost - best.cost) <= 0.005 && sim.months < best.sim.months)) {
          best = { cost: cost, fees: feeSum, sim: sim, built: built, rule: rule, assign: assign.slice() };
        }
      });
    }
    return { base: base, best: best };
  }

  // ---- UI ----
  var CARDS = 4;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }
  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }
  function num(id) { var raw = document.getElementById(id).value.trim(); if (raw === '') return NaN; var v = parseFloat(raw); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }
  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (t) { var td = document.createElement('td'); td.textContent = t; tr.appendChild(td); });
    body.appendChild(tr);
  }
  function aprText(a) { return (a * 100).toFixed(2).replace(/\.?0+$/, '') + '%'; }

  function readCards() {
    var out = [], ok = true;
    for (var i = 1; i <= CARDS; i++) {
      var balEl = document.getElementById('btoBal' + i), aprEl = document.getElementById('btoApr' + i);
      var name = document.getElementById('btoName' + i).value.trim() || ('Card ' + i);
      if (balEl.value.trim() === '' || parseFloat(balEl.value) === 0) {
        balEl.setAttribute('aria-invalid', 'false'); aprEl.setAttribute('aria-invalid', 'false');
        continue;
      }
      var bal = parseFloat(balEl.value), apr = parseFloat(aprEl.value);
      var badBal = isNaN(bal) || bal < 0 || bal > 1e7, badApr = isNaN(apr) || apr < 0 || apr > 100;
      balEl.setAttribute('aria-invalid', String(badBal)); aprEl.setAttribute('aria-invalid', String(badApr));
      if (badBal || badApr) { ok = false; continue; }
      out.push({ name: name, balance: bal, apr: apr / 100 });
    }
    return { ok: ok, cards: out };
  }

  function readOffer(k) {
    var o = { limit: num('btoLimit' + k), fee: num('btoFee' + k) / 100, introApr: num('btoIntro' + k) / 100,
      introMonths: Math.round(num('btoMonths' + k)), apr: num('btoAfter' + k) / 100 };
    var bad = isNaN(o.limit) || o.limit < 0 || o.limit > 1e7 || isNaN(o.fee) || o.fee < 0 || o.fee > 0.2 ||
      isNaN(o.introApr) || o.introApr < 0 || o.introApr > 1 || isNaN(o.introMonths) || o.introMonths < 0 || o.introMonths > 60 ||
      isNaN(o.apr) || o.apr < 0 || o.apr > 1;
    return bad ? null : o;
  }

  function clearResults() {
    ['btoCost', 'btoSaved', 'btoDate', 'btoFees'].forEach(function (id) { set(id, '–'); });
    ['btoCostNote', 'btoSavedNote', 'btoDateNote'].forEach(function (id) { set(id, ''); });
    document.getElementById('btoRule').hidden = true;
    clearBody('btoMove'); clearBody('btoPromo');
  }

  function update() {
    var use2 = document.getElementById('btoUse2').checked;
    document.getElementById('btoOffer2').hidden = !use2;
    var error = document.getElementById('btoError'), problem = '';
    var input = readCards(), budget = num('btoBudget');
    var offers = [readOffer(1)];
    if (use2) offers.push(readOffer(2));
    if (!input.ok) problem = 'Check the highlighted cards: a balance above $0 and an APR from 0 to 100%.';
    else if (!input.cards.length) problem = 'Enter at least one card balance.';
    else if (isNaN(budget) || budget <= 0) problem = 'Enter the total you can pay each month.';
    else if (offers.some(function (o) { return !o; })) problem = 'Check the promo card details: a limit of $0 or more, a fee up to 20%, APRs from 0 to 100% and an intro period up to 60 months.';
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }
    var cards = input.cards, r = optimize(cards, offers, budget);
    if (!r.base.feasible) problem = 'Your monthly total does not cover the minimum payments on these cards. Raise it.';
    else if (!r.best) problem = 'Your monthly total does not keep up with the interest, so no plan clears these cards within 100 years. Raise it.';
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }
    error.hidden = true; error.textContent = '';

    var b = r.best, base = r.base;
    set('btoCost', money.format(b.cost));
    set('btoCostNote', 'Interest ' + money.format(b.sim.interest) + ' + fees ' + money.format(b.fees) + '.');
    if (base.done) {
      set('btoSaved', money.format(Math.max(0, base.interest - b.cost)));
      set('btoSavedNote', 'Without transferring: ' + money.format(base.interest) + ' of interest over ' + duration(base.months) + '.');
    } else {
      set('btoSaved', 'Not comparable');
      set('btoSavedNote', 'Without transferring, this budget never clears the cards.');
    }
    set('btoDate', dateAfter(b.sim.months));
    set('btoDateNote', 'In ' + duration(b.sim.months) + (base.done && base.months !== b.sim.months ? ' (' + duration(base.months) + ' without transferring).' : '.'));
    set('btoFees', money.format(b.fees));
    var rule = document.getElementById('btoRule');
    rule.hidden = false;
    var anyMoved = b.built.moved.some(function (v) { return v > 0; });
    rule.textContent = !anyMoved
      ? 'With these offers, moving a balance does not lower your total cost, so the cheapest plan is to keep each balance where it is and put any money above the minimums on the highest rate.'
      : (b.rule === 'promo'
        ? 'How to pay: cover every minimum, top up each promo card to the payment that clears it before its intro rate ends, then put anything left on the highest rate.'
        : 'How to pay: cover every minimum and put everything left on whichever card has the highest rate that month. Promo balances get paid down once the higher-rate cards are clear.');

    var move = clearBody('btoMove');
    cards.forEach(function (c, i) {
      var m = b.built.moves[i], stays = cents(c.balance - m.reduce(function (s, v) { return s + v; }, 0));
      addRow(move, [c.name, money.format(c.balance), aprText(c.apr), m[0] ? money.format(m[0]) : '–',
        offers.length > 1 && m[1] ? money.format(m[1]) : '–', stays > 0 ? money.format(stays) : '–']);
    });

    var promo = clearBody('btoPromo'), nCards = cards.length;
    offers.forEach(function (o, k) {
      var moved = b.built.moved[k], fee = b.built.fees[k];
      if (!moved) { addRow(promo, ['Promo card ' + (k + 1), 'Not used', '–', '–', '–', '–']); return; }
      var need = o.introMonths ? money.format(Math.ceil(levelPayment(moved + fee, o.introApr, o.introMonths) * 100 - 1e-6) / 100) + '/mo' : 'No intro period';
      var when = b.sim.paidOff[nCards + k];
      var cleared = when > 0 ? dateAfter(when) + (o.introMonths ? (when <= o.introMonths ? ' (in time)' : ' (' + (when - o.introMonths) + ' months after the intro ends)') : '') : '–';
      addRow(promo, ['Promo card ' + (k + 1), money.format(moved), money.format(fee), need,
        o.introMonths ? dateAfter(o.introMonths) : '–', cleared]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('btoForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
